B.aaG=new A.bN("p04","\u0646\u062e\u0644\u0629 \u0627\u0644\u062a\u0645\u0631","Date palm","Phoenix dactylifera",B.oz,B.aj,B.ao,B.d3,7,!1,"\u0627\u0644\u0646\u062e\u0644\u0629 \u0627\u0644\u0645\u0639\u0631\u0648\u0641\u0629\u060c \u062a\u062d\u062a\u0627\u062c \u0634\u0645\u0633\u0627\u064b \u0643\u0627\u0645\u0644\u0629 \u0648\u0631\u064a \u0645\u0646\u062a\u0638\u0645 \u0641\u064a \u0627\u0644\u0635\u064a\u0641.","The classic date palm; full sun and regular summer watering.","RCRC \u2014 Manual of Riyadh Plants",!0,null,"Date palm",null)
B.ab4=new A.bN("p05","\u0627\u0644\u0623\u062b\u0644","Athel tamarisk","Tamarix aphylla",B.d2,B.aj,B.ao,B.ax,10,!1,"\u0634\u062c\u0631\u0629 \u0633\u0631\u064a\u0639\u0629 \u0627\u0644\u0646\u0645\u0648 \u062a\u0633\u062a\u062e\u062f\u0645 \u0643\u0645\u0635\u062f\u0627\u062a \u0631\u064a\u0627\u062d\u060c \u062a\u062a\u062d\u0645\u0644 \u0627\u0644\u0645\u0644\u0648\u062d\u0629.","Fast-growing windbreak tree that tolerates salinity.","RCRC \u2014 Manual of Riyadh Plants",!0,null,null,null)
B.aaQ=new A.bN("p06","\u0627\u0644\u0637\u0644\u062d","Gerrard's acacia","Vachellia gerrardii",B.d2,B.aj,B.ao,B.ax,14,!1,"\u0634\u062c\u0631\u0629 \u0628\u0631\u064a\u0629 \u0645\u062d\u0644\u064a\u0629 \u0645\u0646 \u0634\u062c\u0631 \u0627\u0644\u0631\u0648\u0636\u0627\u062a\u060c \u0642\u0644\u064a\u0644\u0629 \u0627\u0644\u0627\u062d\u062a\u064a\u0627\u062c \u0644\u0644\u0645\u0627\u0621.","Native wild acacia of the Najd meadows; low water needs.","RCRC \u2014 Manual of Riyadh Plants",!0,null,null,null)
