B.aaH=new A.bN("p08","\u0627\u0644\u0628\u0627\u0631\u0643\u0646\u0633\u0648\u0646\u064a\u0627","Jerusalem thorn","Parkinsonia aculeata",B.d2,B.aj,B.ao,B.ax,10,!1,"\u0634\u062c\u0631\u0629 \u0635\u063a\u064a\u0631\u0629 \u0628\u0623\u0632\u0647\u0627\u0631 \u0635\u0641\u0631\u0627\u0621\u060c \u062a\u062a\u062d\u0645\u0644 \u0627\u0644\u062d\u0631 \u0648\u0627\u0644\u062c\u0641\u0627\u0641.","Small tree with yellow flowers; heat and drought tolerant.","RCRC \u2014 Manual of Riyadh Plants",!0,null,null,null)
B.ab7=new A.bN("p09","\u0627\u0644\u0644\u0628\u062e","Siris tree","Albizia lebbeck",B.d2,B.aj,B.ao,B.d3,7,!1,"\u0634\u062c\u0631\u0629 \u0638\u0644 \u0643\u0628\u064a\u0631\u0629 \u0633\u0631\u064a\u0639\u0629 \u0627\u0644\u0646\u0645\u0648\u060c \u062a\u062d\u062a\u0627\u062c \u0645\u0633\u0627\u062d\u0629 \u0648\u0627\u0633\u0639\u0629.","Large fast-growing shade tree; needs plenty of space.","RCRC \u2014 Manual of Riyadh Plants",!0,null,null,null)
B.abd=new A.bN("p10","\u0627\u0644\u0628\u0648\u0646\u0633\u064a\u0627\u0646\u0627","Royal poinciana","Delonix regia",B.d2,B.aj,B.ao,B.d3,5,!1,"\u0634\u062c\u0631\u0629 \u0632\u064a\u0646\u0629 \u0628\u0623\u0632\u0647\u0627\u0631 \u062d\u0645\u0631\u0627\u0621 \u0632\u0627\u0647\u064a\u0629 \u0641\u064a \u0627\u0644\u0635\u064a\u0641.","Ornamental tree with bright red summer flowers.","RCRC \u2014 Manual of Riyadh Plants",!0,null,null,null)
B.aaT=new A.bN("p11","\u0646\u062e\u064a\u0644 \u0627\u0644\u0648\u0627\u0634\u0646\u0637\u0648\u0646\u064a\u0627","California fan palm","Washingtonia filifera",B.oz,B.aj,B.ao,B.d3,7,!1,"\u0646\u062e\u0644\u0629 \u0645\u0631\u0648\u062d\u064a\u0629 \u0627\u0644\u0623\u0648\u0631\u0627\u0642 \u0644\u0644\u0634\u0648\u0627\u0631\u0639 \u0648\u0627\u0644\u062d\u062f\u0627\u0626\u0642 \u0627\u0644\u0643\u0628\u064a\u0631\u0629.","Fan-leaf palm for streets and large gardens.","RCRC \u2014 Manual of Riyadh Plants",!0,null,null,null)
B.ab8=new A.bN("p12","\u0627\u0644\u0634\u062b","Hopbush","Dodonaea viscosa",B.bR,B.aj,B.ao,B.ax,7,!1,"\u0634\u062c\u064a\u0631\u0629 \u0645\u062d\u0644\u064a\u0629 \u062a\u0635\u0644\u062d \u0643\u0633\u064a\u0627\u062c \u0623\u062e\u0636\u0631\u060c \u062a\u062a\u062d\u0645\u0644 \u0627\u0644\u062d\u0631.","Native shrub that makes a good hedge; heat tolerant.","RCRC \u2014 Manual of Riyadh Plants",!0,null,null,null)
